      "type": "∀ {R : Type u_1} [inst : Semiring R] [inst_1 : LinearOrder R] [inst_2 : FloorSemiring R] {a : R} {n : ℕ}\n  [IsStrictOrderedRing R], a ≤ ↑n → ⌊a⌋₊ ≤ n"
    },
