      "name": "Nat.floor_eq_iff",
      "module_name": "Mathlib.Algebra.Order.Floor.Semiring",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] [inst_1 : LinearOrder R] [inst_2 : FloorSemiring R] {a : R} {n : ℕ},\n  0 ≤ a → (⌊a⌋₊ = n ↔ ↑n ≤ a ∧ a < ↑n + 1)"
    },
